-- Resources content for one-time clock changes in On Air (CLAUDE.md, "Resources
-- stay in step with the code"). Content only; no schema. A new guide covers adding
-- a one-time change, switching rundowns already built, and what happens to
-- underwriting credits placed on them.

select private.rc_release_guide(
  p_slug => 'log-one-time-clock-change',
  p_tool_key => 'log',
  p_title => 'Changing a program''s clock for a few days',
  p_summary => 'Give a program a different clock on certain dates, such as FPREN storm coverage, and switch rundowns that were already built.',
  p_screen_keys => array['log.program', 'log.program.schedule'],
  p_sort_order => 60,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a one-time change when a program needs a different clock for a set of dates, for example FPREN Phase I storm coverage. The normal weekly schedule stays as it is, and the one-time change replaces it on the dates you choose."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add the change"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the program from "},{"type":"text","text":"Programs","marks":[{"type":"link","attrs":{"href":"/log/programs"}}]},{"type":"text","text":", then select "},{"type":"text","text":"+ Add a time","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set the entry type to "},{"type":"text","text":"One-time change","marks":[{"type":"bold"}]},{"type":"text","text":", choose the clock, and give the start and end dates, the air time and the length. A one-time change covers every day between its dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Save. On those dates, Today, the week view and any new rundown use this clock instead of the normal one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Switch rundowns that already exist"}]},{"type":"paragraph","content":[{"type":"text","text":"Traffic can build rundowns weeks ahead, so some of those dates may already have a rundown on the old clock. When that is so, the program page shows a notice that lists the dates, with a "},{"type":"text","text":"Switch","marks":[{"type":"bold"}]},{"type":"text","text":" button."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Switching keeps each old rundown as a record and builds a new one on the clock now in force. The old rundown is marked as replaced and can't be started, edited or submitted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a rundown that hasn't started and has nothing recorded on it is switched. One that is on air, or has recorded outcomes, is left as it is."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A rundown created from an imported program log is not switched."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens to underwriting"}]},{"type":"paragraph","content":[{"type":"text","text":"Any underwriting credit already placed on a replaced rundown is recorded as missed, with the reason Special coverage. Each one appears in Traffic's exception list, where staff decide on a makegood or a waiver. Nothing is placed again automatically, and nothing is counted as aired."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"DAD"}]},{"type":"paragraph","content":[{"type":"text","text":"If a date already has a released DAD log, the notice says so. Traffic needs to release a new log for that date, because DAD plays what was released."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Going back"}]},{"type":"paragraph","content":[{"type":"text","text":"To end a change early, shorten its end date or remove the entry, then select "},{"type":"text","text":"Switch","marks":[{"type":"bold"}]},{"type":"text","text":" again on the program page. Exceptions that were already raised stay open for Traffic to resolve."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On Today, a program with a one-time change shows one row, labelled One-time change, not two."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Holiday is no longer an entry type. A holiday that needs a different clock is a one-time change; one that is only automated is set under Automation."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-09-log-one-time-clock-change',
  p_tool_key => 'log',
  p_released_on => '2026-10-09',
  p_title => 'One-time clock changes replace the normal schedule',
  p_guide_slugs => array['log-one-time-clock-change'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A one-time change on a program's schedule now replaces its normal entry on the dates it covers, everywhere the portal decides what airs. If rundowns for those dates were already built, the program page offers to switch them to the new clock. The old rundowns are kept as a record, and any underwriting credit placed on them goes to Traffic's exception list as missed with the reason Special coverage. Holiday is no longer an entry type."}]}]}$body$
);
